        /// <summary>Whether <paramref name="op"/> is an op of the schema.</summary>
        public static bool IsDefined(GraphOp op) => (uint)op < (uint)s_signatures.Length && s_signatures[(int)op].Op == op && op != 0;

        /// <summary>The schema's signature of <paramref name="op"/>.</summary>
        public static GraphOpSignature Signature(GraphOp op)
            => IsDefined(op) ? s_signatures[(int)op] : throw new ArgumentOutOfRangeException(nameof(op), op, "not an op of the graph schema");

        /// <summary>Null when an op of <paramref name="op"/> with these counts fits the schema, else why not.</summary>
        public static string? Check(GraphOp op, int srcs, int ip, int fp)
        {
            if (!IsDefined(op)) return $"op {(int)op} is not an op of the graph schema";
            GraphOpSignature s = s_signatures[(int)op];
            if (srcs < s.SrcsMin || srcs > s.SrcsMax) return Describe(op, "operands", srcs, s.SrcsMin, s.SrcsMax);
            if (ip < s.IpMin || ip > s.IpMax) return Describe(op, "integer parameters", ip, s.IpMin, s.IpMax);
            if (fp < s.FpMin || fp > s.FpMax) return Describe(op, "float parameters", fp, s.FpMin, s.FpMax);
            return null;
        }

        /// <summary>Throws where <see cref="Check"/> finds the counts do not fit the schema.</summary>
        public static void Validate(GraphOp op, int srcs, int ip, int fp)
        {
            if (Check(op, srcs, ip, fp) is { } error) throw new ArgumentException(error);
        }

        private static string Describe(GraphOp op, string what, int count, int min, int max)
            => $"{op} takes {(min == max ? min.ToString() : $"{min}..{max}")} {what} ({SlotNames(op, what)}); the program gave {count}";

