    /// <summary>Anything that records graph ops (<see cref="GraphProgramBuilder"/> and the emitters that wrap it): the
    /// target of the typed emitters of <see cref="GraphOpEmit"/>.</summary>
    public interface IGraphOpEmitter
    {
        int Op(GraphOp op, ReadOnlySpan<int> srcs, ReadOnlySpan<long> ip = default, ReadOnlySpan<float> fp = default);
    }

    /// <summary>Typed emitters of the schema's ops (generated from TensorSharp.Core/Graph/Schema/graph-ops.json): each
    /// takes its operands and parameters by name. An optional operand is left out as -1 (the ones after it must be left
    /// out too); an optional parameter left null is left out of the program with every slot after it, so a program
    /// keeps the bytes and signature an emitter gave it by hand.</summary>
    public static class GraphOpEmit
    {
        /// <summary>Records <see cref="GraphOp.GetRows"/>.</summary>
        public static int EmitGetRows(this IGraphOpEmitter e, int table, int ids)
        {
            Span<int> srcs = stackalloc int[2];
            srcs[0] = table;
            srcs[1] = ids;
            return e.Op(GraphOp.GetRows, srcs, default, default);
        }

