        {
            Span<int> srcs = stackalloc int[1];
            srcs[0] = x;
            Span<float> fp = stackalloc float[1];
            int nfp = 0;
            if (s.HasValue && nfp < 1) nfp = 1;
            if (nfp > 0) fp[0] = s ?? 1f;
