        /// <summary>Records <see cref="GraphOp.RopeExt"/>.</summary>
        public static int EmitRopeExt(this IGraphOpEmitter e, int x, int positions, long nDims, long mode, long nCtxOrig, float freqBase, float freqScale, float extFactor, float attnFactor, float betaFast, float betaSlow, int freqFactors = -1)
        {
            Span<int> srcs = stackalloc int[3];
            srcs[0] = x;
            srcs[1] = positions;
            srcs[2] = freqFactors;
            int ns = 2;
            if (freqFactors >= 0) { if (ns != 2) throw new ArgumentException("RopeExt: optional operand freqFactors follows one left out"); ns = 3; }
            srcs = srcs[..ns];
            Span<long> ip = stackalloc long[3];
            ip[0] = nDims;
